          ["sample"] = "<?php\nuse N\\{ClassName,AnotherClassName,OneMoreClassName};\n$instance = new class {};namespace A {\n#[Attribute] #[Attribute(1,2)] function foo() {return 0;}\n\nfunction bar($x,\n$y, int $z=1) {\n$x = 0;\n// $x = 1\ndo { $y += 1; }\nwhile ($y < 10);\nif (true) $x = 10;\nelseif ($y < 10) $x = 5;\nelse if (true) $x = 5;\nfor($i=0;$i<10;$i++) $yy = $x > 2 ?1:2;\nwhile(true) $x = 0;\ndo {$x += 1;} while (true);\nforeach(array(\"a\"=>0,\"b\"=>1,\n\"c\"=>2) as $e1){echo $e1;}\n$count = 10;\n$x = array(\"x\",\"y\",\narray(1=>\"abc\",\n2=>\"def\",3=>\"ghi\"));\n$zz = array(0.1,0.2,\n0.3,0.4);\n$x = array(\n0 => \"zero\",\n123 => \"one two three\",\n25 => \"two five\"\n);bar(0,bar(1,\n\"b\"));\n}\n\nabstract class Foo extends FooBaseClass implements Bar1, Bar2, Bar3 {\n\n  var $numbers = array(\"one\", \"two\", \"three\", \"four\", \"five\", \"six\");\n var $v = 0; // comment \n public $path = \"root\"; // comment\n\nconst FIRST = 'first';\nconst SECOND = 0;const Z = -1;\n\nfunction bar($v,\n$w=\"a\") {\n$y=$w;\n$result = foo(\"arg1\",\n\"arg2\",\n10);\nswitch($v) {\ncase 0:\nreturn 1;\ncase 1:\necho '1';\nbreak;\ncase 2:\nbreak;\ndefault:\n$result = 10;\n}return $result;\n}\n\n  public static function fOne(#[Attribute(1,2)]$argA, $argB, $argC, $argD, $argE, $argF, $argG, $argH) {\n    $x = $argA + $argB + $argC + $argD + $argE + $argF + $argG + $argH;\n    list($field1, $field2, $field3, $filed4, $field5, $field6) = explode(\",\", $x);\n    fTwo($argA, $argB, $argC, fThree($argD, $argE, $argF, $argG, $argH));\n    $z = $argA == \"Some string\" ? \"yes\" : \"no\";\n    $colors = array(\"red\", \"green\", \"blue\", \"black\", \"white\", \"gray\");\n    $count = count($colors);\n    for ($i = 0; $i < $count; $i++)\t{\n      $colorString = $colors[$i];\n    }\n  }\n\n  function fTwo($strA, $strB, $strC, $strD) {\n    if ($strA == \"one\" || $strB == \"two\" || $strC == \"three\") {\n      return $strA + $strB + $strC;\n    }\n    $x = $foo->one(\"a\", \"b\")->two(\"c\", \"d\", \"e\")->three(\"fg\")->four();\n    $y = a()->b()->c();\n    return $strD;\n  }\n\n  function fThree($strA, $strB, $strC, $strD, $strE) {\n    try {\n}catch(Exception $e){\nfoo();\n}\nfinally {\n // do something\n}\n    return $strA + $strB + $strC + $strD + $strE;\n  }\n\n  protected abstract function fFour();\n\n  abstract public string $name {\n    get;\n    set;\n  }\n\n}\n}\nfunction f($a, $ab, $abc) {}\nf(\na: 1,\nab:2,\nabc:3\n);\nfunction compoundParam(VeryLongTypeName|AnotherLongTypeName|YetAnotherLongTypeName|OneMoreLongName $x): void {}\n$j = 0;\n\nfunction f2(array $arr) {}\nf2([0 => 5,\n    1 => 7,]);\n\necho match($j) {\n0    =>'zero',2 => 'two',\n  42=> 'forty-two',\ndefault=>throw new Exception()\n};\nenum Suit: string\n{\n    case Clubs = 'C';\n    case Diamonds = 'D';\n    case Hearts = 'H';\n    case Spades = 'S';\n}\n$func = fn(\nint $x,\nint $y\n): int =>\n$x + $y;\n$value =\n<<<EOD\n  Example of string\n  spanning multiple lines\n  using heredoc syntax.\n  EOD;\n",
